mapper.select:
SELECT DISTINCT f.id, f.function_type, f.function_type_name, f.sub_function_type, f.sub_function_type_name, f.function_code, f.function_code_name, f.function_detail, f.icon_code, f.icon_colour, f.url, f.des_image_url, f.function_label FROM vm_function_type f left join vm_algorithm_info_t fa ON fa.function_code = f.function_code and fa.app_scenarios = 1 LEFT JOIN vm_order_algorithms oa ON oa.algorithm_code = fa.algorithm_code where oa.delete_flag = '0' and f.delete_flag = '0' and fa.delete_flag = '0' and oa.tenant_id = #{tenantId}
and oa.industry_code = #{industryCode}
and oa.app_ver_code = #{appVerCode}
and oa.ord_status in (0,1,2)

SELECT id, function_type, function_type_name, sub_function_type, sub_function_type_name, function_code, function_code_name, function_detail, icon_code, icon_colour, url, des_image_url, function_label FROM vm_function_type WHERE function_code NOT IN ( SELECT fa.function_code FROM vm_algorithm_info_t fa LEFT JOIN vm_order_algorithms oa ON fa.algorithm_code = oa.algorithm_code WHERE oa.delete_flag = '0' and fa.app_scenarios = 1 and fa.delete_flag = '0' and oa.tenant_id = #{tenantId} and oa.ord_status in (0,1,2)
and oa.industry_code = #{industryCode}
and oa.app_ver_code = #{appVerCode}
) and delete_flag = '0'
